        map["Eventually."] = "À terme, oui.";
        map["I'm leaving now..."] = "Je m'en vais...";
        map["...but I'll be back."] = "...mais je reviendrai.";

        // DialogTalkToGunter & Hagen
        map["Good thinking, Arthur. They're not paying attention at all!"] = "Bien joué, Arthur. Ils ne font absolument pas attention à nous !";
        map["I've got a hand free! I think I can get to my pockets."] = "J'ai une main de libre ! Je crois pouvoir atteindre mes poches.";
        map["Do you have something that can get us out of these binds?"] = "Avez-vous quelque chose pour nous délivrer de ces liens ?";
