        map["You look me in the eye and say that!"] = "Regarde-moi droit dans les yeux pour voir !";
        map["This really isn't necess- oh, I guess we're doing this then?"] = "Ce n'est vraiment pas nécess... oh, je suppose qu'on est partis là-dessus ?";
        map["Herman said one of you is slightly shorter than the other."] = "Herman prétend que l'un de vous deux est un tantinet plus petit que l'autre.";
        map["That's ridiculous, we're identical!"] = "C'est absurde, nous sommes parfaitement identiques !";
