        map["You're maybe a pixel taller, if that!"] = "Tu es peut-être plus grand d'un misérable pixel, et encore !";
        map["Herman believes infrastructure investment is a financial waste!"] = "Herman affirme qu'investir dans les infrastructures est un gouffre financier inutile !";
        map["That's the kind of short-term thinking that leads to crumbling bridges!"] = "C'est exactement ce genre de vision étriquée qui fait s'écrouler les ponts !";
        map["You'd know all about crumbling bridges, Hagen."] = "Tu t'y connais en ponts écroulés, toi, Hagen.";
        map["Hey! That wasn't my fault."] = "Hé ! Ce n'était pas ma faute.";
        map["Herman thinks Hagen is the favourite child of the two."] = "Herman pense que Hagen est le fils préféré de votre mère.";
        map["How dare you!"] = "Comment oses-tu !";
        map["No, he has a point there. It's pretty obvious that she likes me more."] = "Non, il marque un point. C'est évident qu'elle a une préférence pour moi.";
        map["How can there be a favourite when she can barely tell us apart?"] = "Comment peut-elle avoir un chouchou alors qu'elle nous confond tout le temps ?";
