        map["Never mind, it probably wasn't important."] = "Laissez tomber, ce n'était sans doute pas capital.";

        // DialogTalkToHermanCloset
        map["Suit yourself, I'll leave you to it."] = "Comme vous voudrez, je vous laisse à vos occupations.";
        map["What are you doing in there?"] = "Que fabriquez-vous là-dedans ?";
