        map["I have a strong desire to avoid the same fate, Mr Ackerman."] = "J'ai le fervent désir d'éviter de partager son funeste destin, monsieur Ackerman.";

        // DialogTalkToHermanJail
        map["Sorry about the whole train derailment, I hope you're alright."] = "Désolée pour le déraillement du train, j'espère que vous vous portez bien.";
        map["A little warning would have been nice, that's all."] = "Un petit avertissement au préalable n'eût point été de refus, voilà tout.";
        map["Of course."] = "Bien entendu.";
        map["It will make a good addition to my novel, at least."] = "Cela fera au moins une excellente péripétie pour mon roman.";
        map["Is there anything in your cell that could help us, Herman?"] = "Y a-t-il quoi que ce soit dans votre cellule qui pourrait nous aider, Herman ?";
        map["I'm afraid not, but I do have a room with a view."] = "Hélas non, mais je bénéficie au moins d'une chambre avec vue.";
        map["Wait, you have a window in your cell?"] = "Attendez, vous avez une fenêtre dans votre cachot ?";
