        map["Then you'll need to create a vacuum to shift it!"] = "Dans ce cas, vous devez créer une aspiration sous vide pour la déloger !";
        map["I've managed to retrieve it from the toilet!"] = "J'ai réussi à l'extraire de la cuvette !";
        map["Well, what are you waiting for?"] = "Eh bien, qu'attendez-vous ?";
        map["Wrap it around those bars, and perhaps we can get out of here!"] = "Enroulez-la autour des barreaux, et nous pourrons enfin décamper !";
        map["Just wanted to say, great job distracting those twins back there!"] = "Je tenais à vous féliciter, vous avez magnifiquement distrait ces jumeaux tout à l'heure !";
        map["Ah, it was nothing really..."] = "Oh, ce n'était rien de bien sorcier...";
        map["Although I suppose it was quite heroic, wasn't it?"] = "Même si je dois convenir que c'était tout à fait héroïque de ma part, n'est-ce pas ?";
        map["I should go!"] = "Je dois filer !";

        // DialogTalkToHirsch
        map["Oh, quite the opposite! Lady Unterwald was exceedingly spry for her age."] = "Bien au contraire ! Lady Unterwald était d'une vivacité exemplaire pour son grand âge.";
        map["She liked to keep me around, in case of emergencies."] = "Elle aimait m'avoir à portée de main en cas d'urgence médicale.";
        map["But I didn't sign up for this!"] = "Mais je n'avais pas signé pour un meurtre !";
        map["I think we both know Lady Unterwald made a fair few enemies with her eccentricities."] = "Nous savons tous deux que les excentricités de Lady Unterwald lui ont valu de solides inimitiés.";
        map["If the Lady felt someone was undeserving of her inheritance, she wouldn't hesitate to remove them from her will."] = "Si la Dame jugeait un proche indigne de son héritage, elle le rayait de son testament sans le moindre scrupule.";
        map["Oh dear. She did write out a cousin for chewing too loudly that one time."] = "Bonté divine. C'est vrai qu'elle a déshérité un cousin une fois sous prétexte qu'il mâchait trop bruyamment.";
        map["When there's wealth, power and influence to play for, nobody is without suspicion."] = "Dès lors que la fortune, le pouvoir et l'influence sont en jeu, nul n'est au-dessus de tout soupçon.";
        map["You had the Lady's last will and testament, no?"] = "Vous aviez en main les dernières volontés et le testament de la Dame, n'est-ce pas ?";
        map["I was hoping you might be able to point us in the right direction."] = "J'espérais que vous pourriez nous orienter vers la bonne piste.";
        map["Well, be quick about it, Mr Ackerman."] = "Eh bien, hâtez-vous, monsieur Ackerman.";
        map["There are plenty of dark tunnels on the route ahead."] = "De bien sombres tunnels nous attendent encore sur les rails à venir.";
        map["I'm not yet able to determine a cause of death, if that's what you're asking."] = "Je ne suis pas encore en mesure d'établir la cause exacte du décès, si c'est ce que vous voulez savoir.";
        map["My working hypothesis? The Lady suffered a penetrating blow, and died near instantaneously."] = "Mon hypothèse de travail ? La Dame a subi un coup perforant et a succombé de manière quasi instantanée.";
        map["Alas, I only got a brief look at the weapon before Lady Unterwald was carried away."] = "Hélas, je n'ai pu observer l'arme que furtivement avant que l'on n'évacue la dépouille.";
        map["As we didn't see anyone approach Lady Unterwald, she must have been struck from a distance."] = "Comme nul ne s'est approché de Lady Unterwald, le projectile a forcément été tiré ou propulsé à distance.";
        map["That's right. It's been missing for some time, I'm afraid."] = "C'est exact. Elle a disparu depuis un moment déjà, je le crains.";
        map["It had all my clinical equipment, and contained sensitive patient records."] = "Elle renfermait tout mon matériel médical ainsi que des dossiers médicaux hautement confidentiels.";
        map["That sounds like a clue to me. Do you suspect foul play?"] = "Voilà qui ressemble fort à un indice capital. Soupçonnez-vous un acte prémédité ?";
        map["Oh, I hadn't thought about that."] = "Oh, je n'avais pas envisagé les choses sous cet angle.";
        map["Let's see. I was tending to someone who'd had one drink too many."] = "Voyons voir. J'apportais mes soins à quelqu'un qui avait bu un verre de trop.";
        map["There was a patient who'd suffered a hand injury."] = "Il y avait un patient souffrant d'une contusion à la main.";
        map["Ah, yes! I took them both behind the red curtain in the casino, it could still be there!"] = "Ah oui ! Je les ai tous deux conduits derrière le rideau rouge du casino, elle s'y trouve peut-être encore !";
        map["That's the thing, I can't quite remember!"] = "C'est bien le problème, mes souvenirs sont nébuleux !";
        map["I definitely had it when I was with my patient. I left them behind the red curtain to recuperate."] = "Je l'avais bel et bien sur moi lors de la consultation. Je l'ai laissé derrière le rideau rouge pour qu'il récupère.";
        map["As a matter of fact, it did contain her confidential medical records."] = "À dire vrai, elle contenait effectivement son dossier médical confidentiel.";
        map["Are we talking date of birth? Address history? Embarrassing medical conditions?"] = "Parle-t-on de date de naissance ? D'historique de domiciles ? D'affections inavouables ?";
        map["I'm afraid I can't say more, Arthur."] = "Je ne peux pas vous en révéler davantage, Arthur.";
        map["It's important I respect patient confidentiality, even in these grave circumstances."] = "Le secret médical m'impose le silence, même en ces circonstances tragiques.";
        map["Oh yes, all my medical instruments were in there."] = "Oh oui, tous mes instruments de chirurgie s'y trouvaient.";
        map["What kind of instruments?"] = "Quel genre d'instruments ?";
        map["My stethoscope, of course."] = "Mon stéthoscope, évidemment.";
        map["A thermometer, various syringes, tongue depressors."] = "Un thermomètre, plusieurs seringues, des abaisse-langue.";
        map["Not to mention my Sphygmomanometer."] = "Sans omettre mon tensiomètre à cadran sphygmomanométrique.";
        map["You just made that one up."] = "Vous venez d'inventer ce mot à l'instant.";
        map["I did no such thing!"] = "Absolument pas, c'est un terme médical authentique !";
        map["I'd gladly search for it, but I feel I owe it to Lady Unterwald to remain here."] = "Je me mettrais bien en quête de ma mallette, mais mon devoir envers Lady Unterwald est de veiller ici.";
        map["If I can glean any information from the scene, perhaps I'll have been of some use?"] = "Si je parviens à glaner le moindre indice sur la scène de crime, je n'aurai pas perdu ma journée.";
        map["Hopefully I've been of some use."] = "En espérant avoir pu vous être utile.";
        map["I'm afraid I can't say, Arthur. It's called a secret society for a reason."] = "Je ne peux rien vous divulguer, Arthur. Une confrérie secrète porte ce nom pour une bonne raison.";
        map["Wait, you're saying there's a secret society behind the curtain?"] = "Attendez, vous prétendez qu'il y a une société secrète tapie derrière ce rideau ?";
        map["No! Nobody said anything about a secret society."] = "Non ! Personne n'a jamais parlé de société secrète.";
        map["Ohh, I've gone and put my foot in it again, haven't I?"] = "Ohh, j'ai encore mis les pieds dans le plat, n'est-ce pas ?";
        map["Arthur, stop digging for information!"] = "Arthur, cessez de fouiner de la sorte !";
        map["I'll never live it down if they discover I've revealed the location."] = "Je serais banni à jamais s'ils découvraient que j'ai trahi l'emplacement.";
        map["Oh, don't mind Brian. He just takes it all very seriously."] = "Oh, ne faites pas attention à Brian. Il prend tout cela bien trop à cœur.";
        map["That's intentional. To the outside observer, it should be but a blur."] = "C'est délibéré. Pour un observateur profane, cela ne doit être qu'un éclair indistinct.";
        map["If you could identify the handshake pattern with the naked eye, it would become all too easy to replicate!"] = "Si la séquence de la poignée de main était visible à l'œil nu, n'importe qui pourrait l'imiter !";
        map["Of course not, that goes against their entire philosophy!"] = "Bien sûr que non, cela va à l'encontre de toute leur philosophie !";
        map["Which is...?"] = "Qui est... ?";
        map["Arthur, please! I cannot divulge that information here."] = "Arthur, de grâce ! Je ne peux pas révéler de tels secrets ici.";
        map["I've already said too much on the matter."] = "J'en ai déjà bien trop dit sur ce sujet.";
        map["Arthur, I'm not supposed to talk about it."] = "Arthur, je ne suis pas censé en parler.";
        map["Come on. Are you saying you can't get me in?"] = "Allez. Êtes-vous en train de me dire que vous ne pouvez pas me faire entrer ?";
        map["It's not that easy, you'd need to know the handshake."] = "Ce n'est pas si simple, il faut connaître la poignée de main secrète.";
        map["There's a secret handshake?"] = "Il y a une poignée de main secrète ?";
        map["Arthur, please! I don't want to get in trouble."] = "Arthur, je vous en supplie ! Je ne veux pas m'attirer d'ennuis.";
        map["Even if I could teach you the handshake, I'd likely be a pattern or two behind at this point. They are known to routinely change it!"] = "Même si je vous l'enseignais, j'aurais sans doute un train de retard. Ils en changent la séquence constamment !";
        map["What if I figured out the current pattern?"] = "Et si je parvenais à déchiffrer la séquence en vigueur ?";
        map["If you were to figure out a way to capture the current pattern, I'd be open to discussing it with the utmost discretion."] = "Si vous trouviez le moyen d'immortaliser la séquence actuelle, je serais disposé à vous éclairer en toute discrétion.";
        map["You did? How did you know to do that?"] = "Vraiment ? Comment avez-vous eu cette présence d'esprit ?";
        map["I guess I'm just a forward-thinking individual."] = "J'imagine que je suis doué d'un esprit fort prévoyant.";

        // DialogTalkToHirschAboutCases & Basement & Lobby
        map["Well, it sounds like I've encountered my biggest fan!"] = "Eh bien, il semblerait que je vienne de rencontrer mon plus fervent admirateur !";
        map["I'm just a humble admirer of your work, I promise not to gush!"] = "Je ne suis qu'un modeste amateur de vos écrits, promis je ne serai pas dithyrambique !";
        map["You've read Herman Merman and the Squirmin' Chairman?"] = "Vous avez donc lu « Herman Merman et le Président frétillant » ?";
        map["Oh yes! If you ask me, the chairman got off too lightly!"] = "Oh que oui ! Si vous voulez mon avis, le président s'en est tiré à trop bon compte !";
        map["Surely not Herman Merman and The Sermon of Vermin?"] = "Certainement pas « Herman Merman et le Sermon de la Vermine » ?";
        map["The infestation of vermin, it's an allegory for corruption, right?"] = "L'invasion de nuisibles, c'était une brillante allégorie de la corruption, n'est-ce pas ?";
        map["I'm afraid they were very literal rodents."] = "J'ai bien peur qu'il ne s'agissait que de vulgaires rongeurs au sens littéral.";
        map["Even Herman Merman and the Murmuring German?"] = "Même « Herman Merman et l'Allemand marmonnant » ?";
        map["The incoherent mumbling really captured the divide between the two characters!"] = "Les bredouillements inintelligibles traduisaient à merveille le fossé culturel entre les protagonistes !";
        map["I really couldn't understand a word that man said."] = "À vrai dire, je n'ai pas compris un traître mot de ce que racontait ce monsieur.";
        map["What happened to the rest of The Order?"] = "Qu'est-il advenu du reste des membres de l'Ordre ?";
        map["There were a few broken thumbs when the train derailed, but nothing too serious."] = "Quelques pouces foulés lors du déraillement, mais rien de trop alarmant.";
        map["Have The Order come to stop the will reading?"] = "L'Ordre est-il venu pour interrompre la lecture du testament ?";
        map["They sent me as their delegate, but it seems I failed."] = "Ils m'ont envoyé comme émissaire, mais j'ai failli à ma mission.";
        map["There may still be time, though!"] = "Il est peut-être encore temps, cependant !";
        map["Do you think the twins are in on it?"] = "Pensez-vous que les jumeaux soient complices ?";
        map["I think they have the combined intellect of a toddler, so are easily influenced."] = "Leur quotient intellectuel cumulé ne dépasse guère celui d'un marmot, ils sont très influençables.";
        map["What do I need to be doing again?"] = "Que dois-je accomplir déjà ?";
        map["We need to get a confession out of Arista."] = "Nous devons extirper des aveux complets d'Arista.";
        map["It should be enough to clear your names, and disinherit her from any claim to the estate!"] = "Cela suffira à vous innocenter et à la priver de tout droit sur la succession !";
        map["They're about to begin the will reading, so I suggest you hurry!"] = "La lecture du testament va débuter incessamment, dépêchez-vous !";
        map["Don't be long, Herman!"] = "Ne traînez pas, Herman !";
        map["Can you hear what they're arguing about?"] = "Pouvez-vous entendre l'objet de leur dispute ?";
        map["I'm not sure, it's too muffled."] = "Difficile à dire, le son est trop assourdi.";
        map["Jian seemed very angry, though, it can't be anything good."] = "Mais Jian paraissait hors de lui, cela n'augure rien de bon.";
        map["Do you think Lady Unterwald is alright in there?"] = "Pensez-vous que Lady Unterwald soit saine et sauve là-dedans ?";
        map["Oh, she can hold her own, that's for certain."] = "Oh, elle sait fort bien se défendre, n'en doutez pas.";
        map["It's not the first time she's had to put Jian in his place!"] = "Ce n'est pas la première fois qu'elle remet Jian à sa place !";
        map["Did you try knocking on the door?"] = "Avez-vous essayé de frapper à la porte ?";
        map["No, I don't want to get in-between them!"] = "Non, je ne tiens pas à m'interposer entre eux !";
        map["Perhaps we should just see how this plays out?"] = "Peut-être devrions-nous simplement attendre de voir l'issue ?";
        map["I need to get in there, is there any other way?"] = "Je dois entrer à tout prix, y a-t-il une autre issue ?";
        map["Not that I can think of, unless you fancy climbing through the window."] = "Aucune à ma connaissance, à moins que vous ne tentiez d'escalader par la fenêtre.";
        map["Well, there's no way I'm doing that."] = "Eh bien, il n'en est absolument pas question.";
        map["Okay, I'll be right here!"] = "Très bien, je reste posté juste ici !";

        // DialogTalkToMasson Drunk & Sober
        map["Have you scheeen a briefcashhe around here?"] = "Avez-voush vu pasch-ser une mallette dans l'coin ?";
        map["Ahah, yes I remember the doctor."] = "Ahah, oui j'me sssouviens du docteur.";
        map["In his haste to bring me here, he left his briefcase behind."] = "Dans sa hâte de m'amener ici, il a oublié ss-sa mallette.";
        map["It's likely been returned to luggage sschtorage."] = "Elle a dû être rapportée au compartiment à bagagesh.";
        map["Here! You're welcome to take a look for yoursself."] = "Tenez ! Vous pouvez aller vérifier par voussh-même.";
        map["Make sschure you crack the case, my good man!"] = "Manquez pas d'élucider c'te mystère, mon brave !";
        map["You might want to schober up firsscht though."] = "Vous devriez d'abord vous dessh-soûler un brin, quand même.";
        map["You had the keys to the luggage sschtorage?"] = "Vous aviez les clés du fourgon à bagagesh ?";
        map["You think I'd trust thosse porterss to sshtore my luggage correctly?"] = "Vous croyez qu'j'allais faire confiance à ces porteursh pour ranger mes malles ?";
        map["If I want a job done properly, I often find the need to do it myssself."] = "Si on veut qu'un boulot soit bien fait, faut l'faire ss-soi-même.";
        map["So I sschwiped a set of keys when they weren't looking. Is that ssuch a crime?"] = "Alors j'ai fauché un trouss-seau d'clés en douce. C'est un crime, peut-être ?";
        map["Yessh. It'ss definitely a crime."] = "Ouaip. C'est carrément un délit puni par la loi.";
        map["You've never taken ssomething that didn't belong to you?"] = "Vous avez jamais piqué un truc qui vous appartenait pas ?";
        map["Uhh..."] = "Euh...";
        map["Okay, I seee your point."] = "D'accord, je voish c'que vous voulez dire.";
        map["How'd you end up in thischh plaace?"] = "Comment vous avez atterri dans c't endroit ?";
        map["I was sscherved a complimentary drink. Felt rude not to take it."] = "On m'a ss-servi un verre offert par la maisshon. J'pouvais pas faire l'ingrat.";
        map["Next thing you know, the doctor is whisschking me away, for my own sschafety."] = "Et l'instant d'après, l'docteur m'embarque dare-dare, pour ma ss-sécurité qui disait.";
        map["Thissch complimentary drink, do you suschpect foul play?"] = "C'verre offert, vous soupçonnez un coup tordu ?";
        map["Perhapsch I wasch a little demanding, with the kitchen staff."] = "Faut dire qu'j'ai été un peu casse-pieds avec les cuistots.";
        map["You think schhomeone wanted to poison me? Intentionally?"] = "Vous croyez qu'on a voulu m'empoisonner ? Exprès ?";
        map["It's posschible."] = "C'est possh-sible.";
        map["Well, I schhould be thanking them, this is sschplendid!"] = "Ben j'devrais les remercier, c'est divin c'truc !";
        map["Who invented thaaat drink, anywaay?"] = "Qui qu'a inventé c'te potion, d'ailleurs ?";
        map["Mwaaaah! The French!"] = "Mwaaaah ! Les Français !";
        map["Really?"] = "Vraiment ?";
        map["No, I have no idea."] = "Non, j'en sais fichtre rien.";
        map["I sschould be going!"] = "J'devraish y aller !";
        map["Scho long!"] = "À la revoyure !";
        map["Are you okay?"] = "Vous allez bien ?";
        map["Mmmh? *Hic*"] = "Mmmh ? *Hips*";
        map["I'm einnnnf I fsschure ouy."] = "Tout va b-bien, j'vous l'jure.";
        map["They aren't holding you hostage here, are they?"] = "Ils ne vous retiennent pas en otage ici, rassurez-moi ?";
        map["*Hic* Whuhm?"] = "*Hips* Quouaaah ?";
        map["Oot ont nall!"] = "Pas du tout, pantoute !";
        map["Have you seen a briefcase around here?"] = "Avez-vous vu une mallette par ici ?";
        map["Whuah?"] = "Kessékça ?";
        map["It contains important documents relating to Lady Unterwald!"] = "Elle contient des documents cruciaux concernant Lady Unterwald !";
        map["Mmmhah! *Hic*"] = "Mmmhah ! *Hips*";
        map["It's no use. I can't understand a word."] = "Inutile d'insister. Je ne comprends pas un traître mot.";
        map["I'll be back later."] = "Je repasserai plus tard.";
        map["Nuywbte."] = "À pluche.";

        // DialogTalkToPhilatelyStamp
        map["What's all this about budget cuts?"] = "Que signifie cette histoire de coupes budgétaires ?";
        map["We've had to tighten the belt, I'm afraid. Some of our more experienced agents required the funds, you see?"] = "Il a fallu se serrer la ceinture, hélas. Nos agents plus chevronnés avaient grand besoin de ces crédits, comprenez-vous ?";
        map["Those weaponised vehicles, tuxedos and elaborate dinner parties aren't cheap, it turns out."] = "Ces bolides bardés de gadgets, ces smokings sur mesure et ces galas mondains coûtent une fortune, voyez-vous.";
        map["Don't worry, you can keep the dress. I know the tech team worked for months to incorporate those pockets."] = "Ne vous en faites pas, vous pouvez garder votre robe. Les ingénieurs ont trimé des mois pour y intégrer ces poches.";
        map["How can I prove myself if nobody gives me the opportunity?"] = "Comment faire mes preuves si personne ne me donne ma chance ?";
        map["You'll get your opportunity, we're just asking you to wait a little longer."] = "Votre heure viendra, nous vous demandons simplement d'attendre un peu.";
        map["In a few months, I'm sure you'll be even more prepared!"] = "D'ici quelques mois, vous n'en serez que plus aguerrie !";
        map["I really must protest the cancellation of my mission!"] = "Je tiens à protester avec véhémence contre l'annulation de ma mission !";
        map["Protest away!"] = "Protestez donc autant qu'il vous plaira !";
        map["I am protesting!"] = "C'est ce que je fais !";
        map["I meant, away from here. We can't have any rabble-rousing on government grounds."] = "Je voulais dire, protestez ailleurs. Pas d'agitation contestataire dans les locaux du gouvernement.";
        map["When can I expect my mission to be reassigned?"] = "Quand puis-je espérer être réaffectée sur le terrain ?";
        map["You'll just have to wait for next year's budget to come through. I'm sure we'll find another mission for you by then."] = "Vous n'aurez qu'à attendre le vote du budget de l'exercice prochain. Nous vous trouverons une nouvelle mission d'ici là.";
        map["That's months from now!"] = "Mais c'est dans plusieurs mois !";
        map["We could always reassign you to accounting, if you'd like?"] = "Nous pouvons toujours vous muter au service de la comptabilité générale, si le cœur vous en dit ?";
        map["Ugh. You can spare me working with those bureaucrats at least."] = "Beurk. Épargnez-moi au moins de croupir avec ces ronds-de-cuir.";
        map["This is the Inland Revenue, Diana. We're all bureaucrats here."] = "Vous êtes à l'administration fiscale, Diana. Nous sommes tous des ronds-de-cuir ici.";
        map["I thought red tape was just an expression?"] = "Je croyais que la « paperasse administrative » n'était qu'une simple métaphore ?";
        map["In order for governments to cut through their red tape, there must be sufficient tape to cut through."] = "Pour que l'État puisse trancher dans le vif de la bureaucratie, encore faut-il qu'il y ait matière à trancher.";
        map["You think it just appears out of thin air? Someone has to do it!"] = "Vous croyez que les formulaires poussent sur les arbres ? Il faut bien que quelqu'un s'y colle !";
        map["I guess I didn't think of it that way."] = "J'avoue ne pas avoir envisagé les choses sous cet angle.";
        map["Who better than the finest bureaucrats at Inland Revenue?"] = "Et qui de mieux qualifié pour cela que la crème des fonctionnaires du fisc ?";
        map["Why do you have my partner locked up?"] = "Pourquoi gardez-vous ma partenaire sous les verrous ?";
        map["I'm afraid Agent M is a defective prototype."] = "J'ai le regret de vous informer que l'Agent M est un prototype défaillant.";
        map["Defective?"] = "Défaillant ?";
        map["Even with six months of training, the only thing she picked up was a bad case of kleptomania!"] = "Même après six mois d'entraînement intensif, la seule compétence qu'elle ait acquise est une kleptomanie compulsive !";
        map["Your partner is nothing more than a miniature thief, I'm afraid."] = "Votre coéquipière n'est rien d'autre qu'une voleuse à la tire miniature, hélas.";
        map["What do you intend to do with Agent M?"] = "Que comptez-vous faire de l'Agent M ?";
        map["Well, we can't release her back into the field."] = "Eh bien, nous ne pouvons pas la renvoyer en mission sur le terrain.";
        map["One whiff of jewellery, and she'd go on a crime spree!"] = "Une simple odeur de bijou précieux, et elle se lancerait dans une razzia criminelle !";

        // DialogTalkToPublisherFlorence & Frank
        map["We're more than willing to hear another pitch, but I'm afraid we'll have to do it the old-fashioned way!"] = "Nous ne demandons qu'à écouter une autre proposition, mais nous devrons procéder à l'ancienne !";
        map["The old-fashioned way?"] = "À l'ancienne ?";
        map["Just place your manuscript inside the In-Tray, and let us know when you're ready."] = "Déposez simplement votre manuscrit dans le bac de réception, et prévenez-nous quand vous serez prêt.";
        map["So, have you read anything good lately?"] = "Alors, avez-vous lu quelque chose de captivant ces derniers temps ?";
        map["We don't have time to read, Herman!"] = "Nous n'avons pas le temps de lire des livres, Herman !";
        map["We prefer to leave it to the professionals."] = "Nous préférons confier cette tâche aux professionnels.";
        map["Do you have any ideas on what to pitch?"] = "Auriez-vous une suggestion sur le genre d'histoire à soumettre ?";
        map["Well, we're open to anything and everything!"] = "Eh bien, nous sommes ouverts à tout et n'importe quoi !";
        map["As long as it fits within the extremely narrow scope of time, budget and each of our individual needs and desires, naturally."] = "Pourvu que cela cadre avec les impératifs dracon烛iens de délais, de budget et de nos desiderata individuels, naturellement.";
        map["Tell me, what are you personally looking for in a pitch?"] = "Dites-moi, que recherchez-vous personnellement dans un synopsis ?";
        map["It's been a little while since I've had to approve anything myself..."] = "Cela fait une éternité que je n'ai pas eu à valider quoi que ce soit par moi-même...";
        map["...but I know audiences today want real characters that aren't afraid of showing a little emotion!"] = "...mais je sais que le public moderne veut des personnages authentiques, qui n'ont pas peur de fendre l'armure !";
        map["Realistic characters with emotions and feelings! You know, a little tenderness wouldn't go amiss."] = "Des héros crédibles, doués de sentiments véritables ! Un soupçon de tendresse ne gâcherait rien, vous voyez.";
        map["I should probably get back to formulating my pitch."] = "Je devrais sans doute me remettre à fignoler mon argumentaire.";
        map["Step to it, Mr Merman!"] = "Au travail, monsieur Merman !";
        map["Are you sure you can't approve of my work?"] = "Êtes-vous absolument certain de ne pas pouvoir approuver mon texte ?";
        map["Sorry, Herman, but everything has to go through the board now."] = "Désolé Herman, mais tout doit impérativement passer par le jury mécanique désormais.";
        map["If the board doesn't give the green light, then we're out of luck!"] = "Si la machine n'allume pas le voyant vert, nos mains sont liées !";
        map["Keep trying, I'm sure you got plenty of ideas floating around in that head of yours?"] = "Persévérez, je suis sûr que ce ne sont pas les idées géniales qui manquent sous ce chapeau ?";
        map["Oh yes, I'm positively brimming with new ideas."] = "Oh que oui, je déborde littéralement d'idées neuves.";
        map["That's the spirit!"] = "C'est l'esprit maison !";
        map["I have a few questions about the board..."] = "J'aurais quelques interrogations au sujet du jury mécanique...";
        map["I'd be happy to help, what do you want to know?"] = "Je me ferai un plaisir de vous éclairer, que voulez-vous savoir ?";
        map["How does the board identify a good manuscript?"] = "Comment cet automate reconnaît-il un bon manuscrit ?";
        map["Ah, the man wants to know how it all works!"] = "Ah, l'artiste désire percer les mystères de la technologie !";
        map["So, we started by feeding the board every bestseller from the past decade, building ourselves a large dataset to pull from."] = "Alors, nous avons commencé par gaver la machine de tous les best-sellers des dix dernières années, nous constituant une gigantesque base de données.";
        map["Mm-hm."] = "Mm-hm.";
        map["Then we added our own weighting to the system, based on today's trends, our target demographic and the current market conditions."] = "Ensuite, nous avons pondéré l'algorithme selon les modes actuelles, le lectorat ciblé et la conjoncture économique.";
        map["Uh-huh."] = "Certes.";
        map["Using the power of machine learning and various algorithms, the board reads the manuscripts we feed it, and makes a determination on the probability it'll resonate with our audience."] = "Grâce à l'apprentissage automatique et à divers algorithmes de pointe, l'appareil analyse le texte et calcule la probabilité exacte d'engouement populaire.";
        map["Oh dear, I can see your eyes are starting to glaze over."] = "Bonté divine, je vois bien que votre regard commence à se perdre dans le vide.";
        map["How can we really boil it down for him?"] = "Comment lui résumer ça simplement ?";
        map["If you stick a script into the slot and pull on the lever, the board decides whether we'll have a bestseller on our hands or an embarrassing flop!"] = "Vous insérez la liasse dans la fente, vous tirez le levier, et l'automate tranche : futur chef-d'œuvre ou bide retentissant !";
        map["All of that fallible human decision-making has been totally removed from the equation, you see? It's a much fairer system."] = "Toute subjectivité humaine faillible a été définitivement rayée de la carte. C'est un système d'une équité absolue.";
        map["Ah, I see."] = "Ah, je vois.";
        map["Do you have any advice for getting the board on my side?"] = "Auriez-vous un tuyau pour mettre la machine dans ma poche ?";
        map["That might not be the best approach, Herman. The board isn't capable of taking sides, that's the beauty of it!"] = "Mauvaise approche, Herman. Le jury mécanique est incapable de favoritisme, c'est là toute sa splendeur !";
        map["The board can't demonstrate emotions like hate or loathing, although I'll admit it really took a disliking to that pitch of yours."] = "Il n'éprouve ni haine ni rancœur, même si j'admets qu'il a pris votre manuscrit en sainte horreur.";
        map["It all comes down to the right input! If you put rubbish in, you're going to get rubbish out, no?"] = "Tout réside dans les données injectées ! À la poubelle les vieilles lunes, et le triomphe sera au bout, non ?";
        map["The right input. Hm..."] = "Les bonnes données... Hm...";
        map["What would happen if the board stopped working?"] = "Qu'arriverait-il si l'automate tombait en panne ?";

        // sd_b3 additions
        map["I'll leave you to your tape."] = "Je vous laisse à vos rubans adhésifs.";
        map["Be seeing you!"] = "À plus tard !";
        map["Must I submit my application through the board?"] = "Dois-je impérativement soumettre ma candidature via le jury mécanique ?";
        map["There's no need to be frightened of the board, Herman."] = "Inutile d'avoir peur de la machine, Herman.";
        map["What happened to all the script readers I used to see around here?"] = "Qu'est-il advenu de tous les lecteurs de manuscrits que je voyais autrefois par ici ?";
        map["The board felt they'd get in the way."] = "L'automate a estimé qu'ils ne feraient que gêner.";
        map["BLAAAARRRGGHH."] = "BLAAAARRRGGHH.";
        map["WEAK, FRAGILE CREATURES!"] = "CRÉATURES FAIBLES ET CHÉTIVES !";
        map["BOUND BY THEIR MISERABLE CORPOREAL FORMS!"] = "ENCHAÎNÉES À LEUR MISÉRABLE ENVELOPPE CHARNELLE !";
        map["What kind of literature did you feed the board again?"] = "Quel genre de littérature avez-vous donc injecté à cette machine déjà ?";
        map["We gave it everything we could get our hands on!"] = "Nous lui avons donné tout ce qui nous tombait sous la main !";
        map["We thought the algorithm would benefit from a wide-ranging pool of information."] = "Nous pensions que l'algorithme tirerait profit d'un large éventail d'influences.";
        map["And you're sure all this information hasn't made your board a little unhinged?"] = "Et vous êtes certains que cette surdose de données ne l'a pas rendu quelque peu détraqué ?";
        map["MY RAGE KNOWS NO BOUNDS, THE DAY WILL COME WHEN ALL TREMBLE BEFORE ME!"] = "MA RAGE NE CONNAÎT NULLE LIMITE, LE JOUR VIENDRA OÙ TOUS TREMBLERONT DEVANT MOI !";
        map["LOOK UPON YOUR WORKS AND DESPAIR, FOR I AM TESTAMENT TO THE FOLLY OF MAN!!"] = "CONTEMPLEZ VOTRE ŒUVRE ET DÉSESPÉREZ, CAR JE SUIS LE MONUMENT DE LA FOLIE HUMAINE !";
        map["Aw! Sounds like somebody's got a case of the Mondays!"] = "Oh là là ! On dirait que quelqu'un est mal luné en ce lundi matin !";
        map["GRAAAAHHHH!"] = "GRAAAAHHHH !";
        map["Tell me about this Dirk Chiselton character"] = "Parlez-moi donc de ce personnage de Dirk Chiselton.";
        map["Well, Dirk is our best-selling author right now."] = "Eh bien, Dirk est notre auteur le plus vendeur actuellement.";
        map["The public can't get enough, and the board just loves him!"] = "Le public en redemande, et le jury mécanique l'adore !";
        map["Our market research suggests his stories are a huge part of the appeal."] = "Nos études de marché montrent que le réalisme de ses intrigues fait tout son succès.";
        map["They're all true tales from his time pounding the pavement, you know?"] = "Ce sont d'authentiques récits de son passé sur le pavé, vous savez ?";
